    _XW_COL_RE = re.compile(r'<th scope="col" data-col="([a-z0-9-]+)"')
    _XW_COUNT_LINK_RE = re.compile(
        r'<a href="(/crosswalk/([a-z0-9-]+)/#([a-z-]+))">'
        r'(\d+)<span class="vh"> documents?</span></a>'
    )

