    def test_pin_and_copies_are_baseline_1_11_1(self):
        """The 1.9.2 move (the owner's 1.9.1 notice: grclibrary.ai, whose
        documents page prompted the chip states, moves; the 1.9.2 notice:
        move to 1.9.2 instead, with the same steps), item 3b788's move to
        1.10.0, which changed no copied file but the card builder, the move
        to 1.11.0 (maintainer approval 2026-11-06 15:03Z), then the move to
        1.11.1 (CHANGELOG 1.11.1: every site moves, by replacing
        baseline.css): the pin names 1.11.1; the 2 files 1.11.1 changes that
        grc copies (baseline.css and the card builder,
        RELEASE_1_11_1_DIGESTS) carry 1.11.1's SHA256SUMS digests, the 4
        files 1.11.0 changes or adds that 1.11.1 leaves byte-identical
        (palettes.css, NOTICE.md, logos/vendorreplies.png and the palette
        gate, RELEASE_1_11_0_DIGESTS) carry 1.11.0's, and the files
        RELEASE_1_9_2_DIGESTS and RELEASE_1_10_0_CARD_DIGESTS pin, which
        1.11.0 and 1.11.1 leave as they were, carry their releases', each in
        the pin, in the repository and, for the served ones, in the draft
        copy; the card builder and its fonts (item 3b788, spec 7.35) are
        pinned and never served, while the data file template is not copied
        and the site's data file is not pinned (the live card changes only
        after the owner approves a before and after preview); the module
        docstring and the CSP comment name the pinned version."""
        import tomllib
        pin = tomllib.loads(
            (REPO_ROOT / ".baseline" / "pin.toml").read_text(encoding="utf-8")
        )
        self.assertEqual(pin["version"], "1.11.1")
        for key, digest in {**RELEASE_1_11_1_DIGESTS,
                            **RELEASE_1_11_0_DIGESTS}.items():
            self.assertEqual(pin["files"].get(key), digest, f"{key} pin")
            self.assertEqual(
                hashlib.sha256((REPO_ROOT / key).read_bytes()).hexdigest(),
                digest, f"{key} copy")
            if key.startswith(".web/baseline/"):
                out_rel = "assets/baseline/" + key[len(".web/baseline/"):]
                self.assertEqual(
                    hashlib.sha256(self.draft_all[out_rel]).hexdigest(),
                    digest, out_rel)
            else:
                self.assertNotIn(
                    "assets/baseline/" + key[len(".baseline/"):],
                    self.draft_all, f"{key} is never served")
        for key, digest in RELEASE_1_10_0_CARD_DIGESTS.items():
            self.assertEqual(pin["files"].get(key), digest, f"{key} pin")
            self.assertEqual(
                hashlib.sha256((REPO_ROOT / key).read_bytes()).hexdigest(),
                digest, f"{key} copy")
            self.assertNotIn(
                "assets/baseline/" + key[len(".baseline/"):], self.draft_all,
                f"{key} is never served")
        for card_data in ("site-card.example.toml", "site-card.toml"):
            self.assertFalse(
                [key for key in pin["files"] if card_data in key], card_data)
        self.assertFalse(
            (REPO_ROOT / ".baseline" / "site-card.example.toml").exists())
        for key, digest in RELEASE_1_9_2_DIGESTS.items():
            self.assertEqual(pin["files"].get(key), digest, f"{key} pin")
            self.assertEqual(
                hashlib.sha256((REPO_ROOT / key).read_bytes()).hexdigest(),
                digest, f"{key} copy")
            if key.startswith(".web/baseline/"):
                out_rel = "assets/baseline/" + key[len(".web/baseline/"):]
                self.assertEqual(
                    hashlib.sha256(self.draft_all[out_rel]).hexdigest(),
                    digest, out_rel)
        named = re.compile(r"baseline (\d+\.\d+\.\d+)")
        self.assertEqual(named.findall(" ".join(__doc__.split()[:20])),
                         [pin["version"]],
                         "the module docstring names the pinned version")
        source = Path(__file__).read_text(encoding="utf-8")
        csp_comment = re.search(r"^# The draft CSP, copied from (.*)$",
                                source, re.M)
        self.assertEqual(named.findall(csp_comment.group(1)),
                         [pin["version"]],
                         "the CSP comment names the pinned version")

    def test_scheme_switch_ends_the_top_bar_on_every_page(self):
        """Spec 7.33: on every page, the 404 page included, the switch is
        the last child of header.mast, right after nav.nav, and carries the
        hidden attribute in the markup (without script it is never shown)."""
        self.assertIn("404.html", self.draft_html)
        for rel, html in self.draft_html.items():
            masts = re.findall(r'<header class="mast">(.*?)</header>', html,
                               re.S)
            self.assertEqual(len(masts), 1, f"{rel}: one top bar")
            self.assertTrue(
                masts[0].endswith("</nav>" + SCHEME_SWITCH),
                f"{rel}: the switch follows nav.nav as the last child of "
                "header.mast")
            self.assertEqual(masts[0].count('<nav class="nav"'), 1, rel)
            self.assertEqual(html.count("data-scheme-toggle"), 1,
                             f"{rel}: exactly one switch")
            self.assertRegex(
                html, r'<button class="scheme"[^>]*\shidden>',
                f"{rel}: the switch carries the hidden attribute")

    def test_scheme_script_in_head_before_the_stylesheets(self):
        """Spec sections 5 and 7.33: scheme.js loads in <head>, before the
        stylesheets, with data-cfasync="false" before src and no defer or
        async, so a stored scheme applies before the first paint."""
        for rel, html in self.draft_html.items():
            head = html[:html.index("</head>")]
            tags = re.findall(r"<script\b[^>]*/scheme\.js\"[^>]*>", html)
            self.assertEqual(len(tags), 1, f"{rel}: scheme.js loads once")
            self.assertNotRegex(tags[0], r"\b(?:defer|async)\b",
                                f"{rel}: no defer or async on scheme.js")
            self.assertLess(tags[0].index("data-cfasync"),
                            tags[0].index(" src="),
                            f"{rel}: data-cfasync comes before src")
            at = head.find(SCHEME_SCRIPT_TAG)
            self.assertGreater(at, 0, f"{rel}: the exact tag sits in <head>")
            sheet = head.find('<link rel="stylesheet"')
            self.assertGreater(sheet, at,
                               f"{rel}: scheme.js precedes every stylesheet")

