    def test_no_unsplit_compound_has_an_aliased_part(self):
        """Finding XW-GDPR-CHIP-2128 sweep guard: no taxonomy framework
        string outside both instrument maps splits on " / ", " and " or
        ", " into pieces one of which is itself an exact CROSSWALK_ALIASES
        spelling, so a new compound naming an instrument in an aliased form
        fails here until it is split or aliased. Matcher limit: a piece
        naming an instrument in an unaliased form (for example "EU GDPR
        (Regulation 2016/679)") is not caught, and neither is a compound
        whose instrument part is unaliased."""
        aliases = self.mod.CROSSWALK_ALIASES
        parts = self.mod.CROSSWALK_ALIAS_PARTS
        names = {n for d in self._full_taxonomy()
                 for n in d.get("frameworks", [])}
        unsplit = sorted(
            name for name in names
            if name not in aliases and name not in parts
            and any(piece in aliases for joiner in (" / ", " and ", ", ")
                    for piece in name.split(joiner) if piece != name))
        self.assertEqual(unsplit, [])

    # -- 41. the standards and frameworks page -------------------------------

    _STANDARDS_REGISTER_COLUMNS = [
        "Standard ID", "Current version", "Publication date", "Topic",
        "Superseded versions", "Upstream check location",
        "Last verified (UTC)"]
    _STANDARDS_GROUP_RE = re.compile(
        r'<h2 id="([^"]+)">([^<]*)</h2>\s*<ul>(.*?)</ul>', re.S)
    _STANDARDS_ITEM_RE = re.compile(
        r'<li><span class="row-name">(.*?)</span>'
        r'<span class="row-desc">(.*?)</span></li>', re.S)

    def _register_sections(self):
        """An independent reparse of the citations register: ``(heading,
        [row cells, ...])`` per ``##`` section in register order, rows under
        the register's exact seven-column header only (so a prose section or
        the AI security tooling references table contributes none), raw cell
        strings."""
        text = (REPO_ROOT / "governance"
                / "register-canonical-citations.md").read_text(
                    encoding="utf-8")
        sections = []
        heading = None
        state = "outside"
        for line in text.splitlines():
            if line.startswith("## "):
                heading = line[len("## "):].strip()
                state = "outside"
                continue
            if not line.strip().startswith("|"):
                state = "outside"
                continue
            cells = [c.strip() for c in line.strip().strip("|").split("|")]
            if cells == self._STANDARDS_REGISTER_COLUMNS:
                state = "header"
                continue
            if state == "header":
                state = "rows"
                if not sections or sections[-1][0] != heading:
                    sections.append((heading, []))
                continue
            if state == "rows":
                sections[-1][1].append(cells)
        return [(h, rows) for h, rows in sections if rows]

    # Literal expected headings for representative register rows (round 3:
