class MatrixScriptFixtureTests(unittest.TestCase):
    """6: the rule that matrix.js loads exactly on a page with a matrix
    (spec section 7.30 and section 8), on fixtures, so the render test above
    cannot pass while no rendered page has a
    matrix (round-1 ERROR: False equalled False on every page)."""

    SCRIPT = '<script src="/assets/baseline/matrix.js" defer></script>'
    MATRIX = ('<div class="tablewrap bounded" tabindex="0">'
              '<table class="matrix sticky sticky-col" data-matrix></table>'
              "</div>")
    PLAIN = ('<div class="tablewrap" tabindex="0"><table class="fixed">'
             "</table></div>")

    def test_matrix_page_loads_matrix_js(self):
        self.assertEqual(_matrix_script_faults(self.SCRIPT + self.MATRIX), [])

    def test_page_without_a_matrix_omits_matrix_js(self):
        self.assertEqual(_matrix_script_faults(self.PLAIN), [])

    def test_matrix_without_matrix_js_is_found(self):
        self.assertEqual(_matrix_script_faults(self.MATRIX),
                         ["a data-matrix table without matrix.js"])

    def test_matrix_js_without_a_matrix_is_found(self):
        self.assertEqual(_matrix_script_faults(self.SCRIPT + self.PLAIN),
                         ["matrix.js without a data-matrix table"])

    def test_second_matrix_is_found(self):
        self.assertEqual(
            _matrix_script_faults(self.SCRIPT + self.MATRIX + self.MATRIX),
            ["2 matrices (1 per page, spec 7.30)"])


class CrosswalkPresetGroupTests(unittest.TestCase):
    """29 to 31: the views equal the topic views, and the generator refuses
    every way the topics, the groups and the instruments could disagree, so
    a column can never fall out of every topic, a topic can never show
    nothing or a column the table has not, and an instrument can never fall
    out of the side list silently."""

    @classmethod
    def setUpClass(cls):
        cls.mod = _load_build()

    def _with(self, key, **changes):
        return tuple(i._replace(**changes) if i.key == key else i
                     for i in self.mod.CROSSWALK_INSTRUMENTS)

    def _topic(self, slug, **changes):
        return tuple(t._replace(**changes) if t.slug == slug else t
                     for t in self.mod.CROSSWALK_TOPICS)

    def test_presets_are_the_topics(self):
        presets = self.mod.crosswalk_presets()
        self.assertEqual(
            [(p.slug, p.label, p.columns, p.related) for p in presets],
            list(DraftSiteRenderTests._XW_TOPICS))
        self.assertEqual(presets, self.mod.CROSSWALK_TOPICS)

    def test_topic_with_no_column_raises(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "topic 'canada' has no column"):
            self.mod.crosswalk_presets(topics=self._topic("canada",
                                                          columns=()))

    def test_unknown_instrument_in_a_topic_raises(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "names instrument 'soc-2', which is no "
                                    "crosswalk instrument"):
            self.mod.crosswalk_presets(topics=self._topic(
                "security", columns=("iso-iec-27001", "soc-2")))

    def test_page_only_instrument_as_a_topic_column_raises(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "names 'pipeda' as a column, but it has "
                                    "no main-table column"):
            self.mod.crosswalk_presets(topics=self._topic(
                "canada", columns=("pip", "pipeda")))

    def test_unknown_related_instrument_raises(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "relates instrument 'no-such-instrument', "
                                    "which is no crosswalk instrument"):
            self.mod.crosswalk_presets(topics=self._topic(
                "privacy", related=("pipeda", "no-such-instrument")))

    def test_column_in_no_topic_raises(self):
        topics = self._topic("security", columns=(
            "iso-iec-27001", "nist-csf", "nist-sp-800-53", "csa-ccm"))
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "'aicpa-tsc' has a main-table column in "
                                    "no topic"):
            self.mod.crosswalk_presets(topics=topics)

    def test_instrument_outside_every_group_raises(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "which is no crosswalk group"):
            self.mod.crosswalk_presets(self._with("gdpr", group="Privacy"))

    def test_column_instrument_in_the_also_group_raises(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "belongs to a column group"):
            self.mod.crosswalk_presets(
                self._with("gdpr", group="Also in the corpus"))

    def test_page_only_instrument_in_a_column_group_raises(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "belongs to 'Also in the corpus'"):
            self.mod.crosswalk_presets(
                self._with("cobit", group="Laws and regulations"))

    # 31: round 3 items 8 and 9, and the spec 7.30 header's organization tag.

    def test_duplicate_topic_slug_raises(self):
        topics = self.mod.CROSSWALK_TOPICS + (
            self.mod.CROSSWALK_TOPICS[0]._replace(label="Security again"),)
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "duplicate topic slug 'security'"):
            self.mod.crosswalk_presets(topics=topics)

    def test_topic_slug_all_raises(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "topic slug 'all' is the All view's "
                                    "preset id"):
            self.mod.crosswalk_presets(topics=tuple(
                t._replace(slug="all") if t.slug == "canada" else t
                for t in self.mod.CROSSWALK_TOPICS))

    def test_column_repeated_within_a_topic_raises(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "topic 'trade' names column 'pip' more "
                                    "than once"):
            self.mod.crosswalk_presets(topics=self._topic("trade", columns=(
                "ctpat", "pip", "basc", "wco-safe", "aeo", "pip")))

    def test_main_table_instrument_with_no_org_raises(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "main-table instrument 'gdpr' has no "
                                    "organization tag"):
            self.mod.crosswalk_presets(self._with("gdpr", org=None))

    def test_bad_topic_fails_the_build_not_the_import(self):
        """Round 3 item 8: the presets are validated in build_crosswalk, not
        at import, so a bad topic reports as a generator failure (main
        catches the BuildError the render raises) and an importer of the
        module does not break. The module is loaded from its own source with
        one topic emptied: the load succeeds and the build refuses."""
        path = REPO_ROOT / ".web" / "build.py"
        source = path.read_text(encoding="utf-8")
        good = ('CrosswalkPreset("canada", "Canada",\n'
                '                    ("pip",), ("pipeda", "quebec-law-25")),')
        self.assertEqual(source.count(good), 1, "the fixture finds its topic")
        bad = source.replace(good, good.replace('("pip",)', "()"))
        namespace = {"__name__": "web_build_bad_topic",
                     "__file__": str(path)}
        exec(compile(bad, str(path), "exec"), namespace)
        self.assertNotIn("CROSSWALK_PRESETS", namespace,
                         "no preset table is built at import")
        full = namespace["parse_taxonomy_full"](
            namespace["TAXONOMY"].read_text(encoding="utf-8"))
        with self.assertRaisesRegex(namespace["BuildError"],
                                    "topic 'canada' has no column"):
            namespace["build_crosswalk"](full)


class AdopterDocsFixtureTests(unittest.TestCase):
    """18, 19 and 21: the docs/ metadata reader's loud failure classes, on
    fixtures (round-2 fixes 1, 2, 7 and 8: only the leading block is read,
    the full 13-field model is validated, related documents resolve by link
    target, and nothing, README.md included, is skipped silently).
    parse_adopter_docs reads ADOPTER_DOCS_DIR; each test points it at a
    doctored tree and restores it."""

    FIELDS = (
        ("Document Title", "Fixture Guide"),
        ("Document Type", "Guide"),
        ("Version", "1.0.0"),
        ("Date", "2026-11-03"),
        ("Owner", "Governance Library Maintainer"),
        ("Approving Authority", "Governance Library Maintainer"),
        ("Related Documents", "[`docs/adopter-guide.md`](adopter-guide.md)"),
        ("Classification", "Public"),
        ("Category", "Documentation"),
        ("Review Frequency", "Annual"),
        ("Repository Path", "[`docs/fixture.md`](fixture.md)"),
        ("Confidentiality", "Public"),
        ("License", "CC BY-SA 4.0"),
    )

    @classmethod
    def setUpClass(cls):
        cls.mod = _load_build()

    def _block(self, overrides=None, drop=(), extra=()):
        fields = [(n, v) for n, v in self.FIELDS if n not in drop]
        if overrides:
            fields = [(n, overrides.get(n, v)) for n, v in fields]
        fields += list(extra)
        lines = []
        for i, (name, value) in enumerate(fields):
            suffix = "\\" if i < len(fields) - 1 else ""
            lines.append(f"**{name}:** {value}{suffix}")
        return "\n".join(lines)

    def _doc(self, overrides=None, drop=(), extra=()):
        return (
            "# Fixture guide\n\n" + self._block(overrides, drop, extra)
            + "\n\n---\n\n## Overview\n\nA fixture paragraph.\n"
        )

    def _parse(self, files):
        root = Path(tempfile.mkdtemp(prefix="adopter-docs-"))
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        for name, text in files.items():
            (root / name).write_text(text, encoding="utf-8")
        original = self.mod.ADOPTER_DOCS_DIR
        self.mod.ADOPTER_DOCS_DIR = root
        try:
            return self.mod.parse_adopter_docs()
        finally:
            self.mod.ADOPTER_DOCS_DIR = original

    def test_clean_fixture_parses(self):
        records = self._parse({"fixture.md": self._doc()})
        self.assertEqual([r["title"] for r in records], ["Fixture Guide"])
        self.assertEqual(records[0]["purpose"], "A fixture paragraph.")
        self.assertEqual(records[0]["related_documents"],
                         ["docs/adopter-guide.md"])

    def test_fenced_example_block_never_reads_as_the_document(self):
        """Round-2 ERROR 1: with a guide's real block removed, the old
        scanner read the fenced example's block as the document instead of
        failing; only the leading block may count."""
        body = (
            "# Fixture guide\n\nIntro prose, no metadata block.\n\n"
            "```markdown\n# Example\n\n" + self._block() + "\n```\n\n"
            "## Overview\n\nA fixture paragraph.\n"
        )
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "no leading metadata block"):
            self._parse({"fixture.md": body})

    def test_a_file_without_a_block_fails(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "no leading metadata block"):
            self._parse({"fixture.md": "# Fixture guide\n\nProse only.\n"})

    def test_a_blank_line_mid_block_fails_loudly(self):
        """Round-2 ERROR 2: a blank line mid-block dropped every later
        field silently (the first four satisfied the old check)."""
        lines = self._block().splitlines()
        lines.insert(4, "")
        doc = "# Fixture guide\n\n" + "\n".join(lines) + "\n\n---\n"
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "missing metadata field"):
            self._parse({"fixture.md": doc})

    def test_a_missing_license_fails(self):
        """Round-2 ERROR 2: a missing License rendered an empty licence."""
        with self.assertRaisesRegex(self.mod.BuildError, "License"):
            self._parse({"fixture.md": self._doc(drop=("License",))})

    def test_an_unknown_field_name_fails(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "unknown metadata field"):
            self._parse(
                {"fixture.md": self._doc(extra=(("Colour", "Blue"),))})

    def test_an_invalid_date_fails(self):
        for bad in ("2026-13-40", "26-10-26", "2026/10/26"):
            with self.subTest(date=bad):
                with self.assertRaisesRegex(self.mod.BuildError,
                                            "invalid Date"):
                    self._parse({"fixture.md": self._doc({"Date": bad})})

    def test_an_invalid_version_fails(self):
        # The last is a non-ASCII digit: the site rule takes ASCII digits
        # only (round-3 note 7).
        for bad in ("v1.2.3", "1.2", "1.2.3-rc1", "1.0.١"):
            with self.subTest(version=bad):
                with self.assertRaisesRegex(self.mod.BuildError,
                                            "invalid Version"):
                    self._parse(
                        {"fixture.md": self._doc({"Version": bad})})

    def test_version_rule_agrees_with_the_corpus_rule(self):
        """Round-4 WARN 2: the round-3 site rule refused a leading zero
        ('01.0.0') that the corpus metadata gate, which covers docs/, and
        the maturity heuristic both accept, so one file could pass
        lint-metadata and fail the site build. Every version string below,
        leading zeros included, is judged the same by all three."""
        gate = _load_module(
            ".corpus-management/tools/gate_lint_metadata.py",
            "gate_lint_metadata_draft_mod")
        portal = _load_module("tools/build-portal.py",
                              "portal_version_draft_mod")
        versions = ("01.0.0", "1.00.0", "1.0.01", "00.0.0", "0.0.1",
                    "1.0.0", "10.20.30", "3.0.11", "v1.2.3", "1.2",
                    "1.2.3-rc1", "1.2.3.400", "1..0")
        for version in versions:
            with self.subTest(version=version):
                gate_ok = bool(gate.VERSION_RE.match(version))
                try:
                    portal.classify_maturity(
                        {"path": "docs/fixture.md", "version": version})
                    portal_ok = True
                except SystemExit:
                    portal_ok = False
                try:
                    self._parse(
                        {"fixture.md": self._doc({"Version": version})})
                    site_ok = True
                except self.mod.BuildError as e:
                    self.assertIn("invalid Version", str(e))
                    site_ok = False
                self.assertEqual(site_ok, gate_ok, "site and corpus gate")
                self.assertEqual(portal_ok, gate_ok,
                                 "maturity heuristic and corpus gate")
        self.assertTrue(gate.VERSION_RE.match("01.0.0"),
                        "the corpus rule accepts a leading zero")

    def test_module_docstring_agrees_with_the_version_rule(self):
        """NOTE fix: PR 9's round-3 docstring item said a Version with a
        leading zero fails the build, which round 4 reversed (item 21: a
        leading zero is accepted). The docstring must never claim a leading
        zero fails while the rule accepts one: every docstring sentence
        naming a leading zero must be an accepted-form sentence."""
        self.assertIsNotNone(self.mod._ADOPTER_VERSION_RE.match("01.0.0"),
                             "the site rule accepts a leading zero")
        mentions = [s for s in re.split(r"(?<=[.;])\s+", __doc__)
                    if "leading zero" in s]
        self.assertTrue(mentions, "the docstring states the rule")
        for sentence in mentions:
            self.assertIn("accepted", sentence, sentence)
            self.assertNotIn("fail", sentence, sentence)

    def test_a_repeated_field_name_fails(self):
        """Round-3 WARN 2: a second Version line overwrote the first
        silently, so the page showed whichever came last."""
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "repeats metadata field 'Version'"):
            self._parse(
                {"fixture.md": self._doc(extra=(("Version", "9.9.9"),))})

    def test_a_related_entry_the_parser_cannot_keep_fails(self):
        """Round-3 note 5: a Related Documents link without backticked text,
        or whose target is not a .md file, was dropped silently, and so was
        an entry that is not a link at all."""
        cases = (
            ("[adopter guide](adopter-guide.md)", "cannot keep"),
            ("[`docs/adopter-guide.md`](adopter-guide.md#modes)",
             "cannot keep"),
            ("[`LICENSE`](../LICENSE)", "cannot keep"),
            ("[`docs/adopter-guide.md`](adopter-guide.md), "
             "governance/register-glossary.md", "not a link"),
        )
        for value, message in cases:
            with self.subTest(value=value):
                with self.assertRaisesRegex(self.mod.BuildError, message):
                    self._parse({"fixture.md": self._doc(
                        {"Related Documents": value})})

    def test_a_related_target_that_is_not_a_tracked_repo_file_fails(self):
        """Round-4 note 4: a backticked link over a .md target was kept
        whatever the target named, so an absolute URL, a path outside the
        repository, and a missing file each rendered as a broken link."""
        cases = (
            ("an absolute URL",
             "[`docs/portal.md`](https://github.com/jposluns/grc_library/"
             "blob/main/docs/portal.md)"),
            ("a path outside the repository",
             "[`outside.md`](../../outside.md)"),
            ("an absolute filesystem path", "[`outside.md`](/outside.md)"),
            ("a missing file",
             "[`docs/no-such-file.md`](no-such-file.md)"),
        )
        for what, value in cases:
            with self.subTest(what=what):
                with self.assertRaisesRegex(
                        self.mod.BuildError,
                        "not a tracked file inside the repository"):
                    self._parse({"fixture.md": self._doc(
                        {"Related Documents": value})})

    def test_an_untracked_related_target_fails(self):
        """Round-4 note 4 companion: a file on disk that git does not track
        is not published, so its link would break too. The tracked set is
        git's answer; here it is narrowed to leave out the fixture's real,
        present target (docs/adopter-guide.md)."""
        self.assertTrue((REPO_ROOT / "docs" / "adopter-guide.md").is_file())
        original = self.mod._tracked_repo_files
        self.mod._tracked_repo_files = lambda: {"docs/portal.md"}
        try:
            with self.assertRaisesRegex(
                    self.mod.BuildError,
                    "not a tracked file inside the repository"):
                self._parse({"fixture.md": self._doc()})
        finally:
            self.mod._tracked_repo_files = original

    def _doctored_repo_root(self):
        """A doctored repository root for the two target-resolution tests
        (NOTE fix: the check's is_file() and resolve() clauses had no test),
        restored after the test."""
        repo = Path(tempfile.mkdtemp(prefix="adopter-repo-"))
        self.addCleanup(shutil.rmtree, repo, ignore_errors=True)
        (repo / "docs").mkdir()
        original_root = self.mod.REPO_ROOT

        def restore():
            self.mod.REPO_ROOT = original_root

        self.addCleanup(restore)
        self.mod.REPO_ROOT = repo
        return repo

    def test_a_tracked_target_with_no_file_on_disk_fails(self):
        """NOTE fix: tracked-set membership alone is not enough; the
        is_file() clause must refuse a tracked path whose file is absent
        from the work tree (a stale or doctored tracked set)."""
        self._doctored_repo_root()
        original = self.mod._tracked_repo_files
        self.mod._tracked_repo_files = lambda: {"docs/ghost.md"}
        try:
            with self.assertRaisesRegex(
                    self.mod.BuildError,
                    "not a tracked file inside the repository"):
                self._parse({"fixture.md": self._doc(
                    {"Related Documents": "[`docs/ghost.md`](ghost.md)"})})
        finally:
            self.mod._tracked_repo_files = original

    def test_a_tracked_symlink_target_fails(self):
        """NOTE fix: a tracked symlink passes the membership and is_file()
        clauses (is_file follows links), so the resolve() clause must refuse
        it; a symlinked target would publish a link to a page the build
        never renders under that path."""
        repo = self._doctored_repo_root()
        real = repo / "elsewhere.md"
        real.write_text("# elsewhere\n", encoding="utf-8")
        (repo / "docs" / "alias.md").symlink_to(real)
        self.assertTrue((repo / "docs" / "alias.md").is_file(),
                        "the symlink passes the file-presence clause")
        original = self.mod._tracked_repo_files
        self.mod._tracked_repo_files = lambda: {"docs/alias.md"}
        try:
            with self.assertRaisesRegex(
                    self.mod.BuildError,
                    "not a tracked file inside the repository"):
                self._parse({"fixture.md": self._doc(
                    {"Related Documents": "[`docs/alias.md`](alias.md)"})})
        finally:
            self.mod._tracked_repo_files = original

    def test_related_target_variable_does_not_shadow_the_parse_loop(self):
        """NOTE fix: inside parse_adopter_docs the Related Documents target
        path was assigned to ``path``, the parse loop's own variable (the
        docs/ file under parse), so any later use of ``path`` in the loop
        body would silently mean the last related target instead of the
        file. The inner name is target_path."""
        source = inspect.getsource(self.mod.parse_adopter_docs)
        self.assertIn("target_path = REPO_ROOT / target", source)
        self.assertNotRegex(source, r"(?<![\w])path = REPO_ROOT",
                            "the loop variable 'path' is never reassigned")

    def test_an_unknown_document_type_fails(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "DRAFT_TYPE_PLURALS"):
            self._parse(
                {"fixture.md": self._doc({"Document Type": "Essay"})})

    def test_an_empty_directory_fails(self):
        with self.assertRaisesRegex(self.mod.BuildError,
                                    "no adopter documents"):
            self._parse({})

    def test_a_missing_directory_fails(self):
        root = Path(tempfile.mkdtemp(prefix="adopter-gone-"))
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        original = self.mod.ADOPTER_DOCS_DIR
        self.mod.ADOPTER_DOCS_DIR = root / "absent"
        try:
            with self.assertRaisesRegex(self.mod.BuildError, "not found"):
                self.mod.parse_adopter_docs()
        finally:
            self.mod.ADOPTER_DOCS_DIR = original

    def test_a_readme_is_not_silently_skipped(self):
        """Round-2 note 2: a docs/README.md was skipped silently; it must
        carry the block like any other docs/ file or fail the build."""
        with self.assertRaisesRegex(self.mod.BuildError, "docs/README.md"):
            self._parse({
                "fixture.md": self._doc(),
                "README.md": "# docs\n\nAn index, no block.\n",
            })

    def test_related_documents_resolve_by_target_not_text(self):
        """Round-2 fix 7 (agy F5): the old parser kept the link TEXT, so a
        descriptive text lost its link; the target, normalized from docs/,
        names the file."""
        doc = self._doc({"Related Documents":
                         "[`the adopter guide`](adopter-guide.md), "
                         "[`the glossary`](../governance/register-glossary.md)"})
        records = self._parse({"fixture.md": doc})
        self.assertEqual(records[0]["related_documents"],
                         ["docs/adopter-guide.md",
                          "governance/register-glossary.md"])

    def test_a_leading_bold_run_in_label_is_stripped(self):
        """Round-2 note 1: a lede opened 'Purpose. A public bibliography...'
        with the run-in label flattened into the prose."""
        body = ("# Fixture guide\n\n" + self._block()
                + "\n\n---\n\n## Overview\n\n"
                + "**Purpose.** A fixture bibliography.\n")
        records = self._parse({"fixture.md": body})
        self.assertEqual(records[0]["purpose"], "A fixture bibliography.")


class DraftCardFixtureTests(unittest.TestCase):
    """40: the build checks around the link-preview card, on fixtures: a
    tampered, missing, non-PNG or wrong-size card fails load_card_bytes, and
    draft_head_tag_block refuses a page carrying its own canonical, og: or
    twitter: tag, a page without exactly one title, meta description or head
    close, an empty value, and a double quote in a value."""

    @classmethod
    def setUpClass(cls):
        cls.mod = _load_build()

    @staticmethod
    def _page(title="<title>Fixture | GRCLibrary.ai</title>",
              description=('<meta name="description" '
                           'content="A fixture page.">'),
              head=""):
        return ("<!doctype html>\n<html><head>\n"
                f"{description}\n{title}\n{head}\n</head>\n"
                "<body><p>body</p></body></html>\n")

    def test_head_tag_block_carries_the_page_title_and_description(self):
        url = "https://grclibrary.ai/fixture/"
        block = self.mod.draft_head_tag_block(
            "fixture.html", self._page(), url)
        self.assertIn(f'<link rel="canonical" href="{url}">', block)
        self.assertIn(f'<meta property="og:url" content="{url}">', block)
        self.assertIn('<meta property="og:title" '
                      'content="Fixture | GRCLibrary.ai">', block)
        self.assertIn('<meta property="og:description" '
                      'content="A fixture page.">', block)
        self.assertIn('<meta name="twitter:card" '
                      'content="summary_large_image">', block)
        self.assertIn('<meta property="og:image" content='
                      '"https://grclibrary.ai/images/grclibrary-card.png">',
                      block)

    def test_page_with_its_own_card_tag_or_canonical_refuses(self):
        for head in (
            '<link rel="canonical" href="https://grclibrary.ai/">',
            '<meta property="og:type" content="website">',
            '<meta name="twitter:card" content="summary">',
        ):
            with self.assertRaises(self.mod.BuildError, msg=head):
                self.mod.draft_head_tag_block(
                    "fixture.html", self._page(head=head),
                    "https://grclibrary.ai/fixture/")

    def test_page_without_one_title_and_description_refuses(self):
        cases = (
            dict(description=""),
            dict(description='<meta name="description" content="A.">'
                             '<meta name="description" content="B.">'),
            dict(description='<meta name="description" content="  ">'),
            dict(title=""),
            dict(title="<title>A</title><title>B</title>"),
            dict(title='<title>Say &quot;hi&quot; "quoted"</title>'),
        )
        for kwargs in cases:
            with self.assertRaises(self.mod.BuildError, msg=kwargs):
                self.mod.draft_head_tag_block(
                    "fixture.html", self._page(**kwargs),
                    "https://grclibrary.ai/fixture/")

    def test_page_without_exactly_one_head_close_refuses(self):
        for page in (self._page() + "</head>",
                     self._page().replace("</head>", "")):
            with self.assertRaises(self.mod.BuildError, msg=page[-40:]):
                self.mod.draft_head_tag_block(
                    "fixture.html", page, "https://grclibrary.ai/fixture/")

    def test_tampered_or_missing_card_fails_the_build(self):
        source = (REPO_ROOT / ".web" / "static" / "images"
                  / "grclibrary-card.png")
        root = Path(tempfile.mkdtemp(prefix="draft-card-"))
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        data = bytearray(source.read_bytes())
        data[-1] ^= 0xFF
        bad = root / "grclibrary-card.png"
        bad.write_bytes(bytes(data))
        with self.assertRaises(self.mod.BuildError):
            self.mod.load_card_bytes(bad)
        with self.assertRaises(self.mod.BuildError):
            self.mod.load_card_bytes(root / "missing.png")
        self.assertEqual(self.mod.load_card_bytes(source),
                         source.read_bytes())

    def test_card_that_is_not_a_1200_by_630_png_fails_the_build(self):
        root = Path(tempfile.mkdtemp(prefix="draft-card-"))
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        header = (b"\x89PNG\r\n\x1a\n" + (13).to_bytes(4, "big") + b"IHDR"
                  + (600).to_bytes(4, "big") + (630).to_bytes(4, "big")
                  + b"\x08\x06\x00\x00\x00" + b"\x00\x00\x00\x00")
        small = root / "grclibrary-card.png"
        small.write_bytes(header)
        with self.assertRaises(self.mod.BuildError):
            self.mod.load_card_bytes(
                small,
                expected_sha256=hashlib.sha256(header).hexdigest())
        not_png = root / "not-a-card.png"
        not_png.write_bytes(b"GIF89a not a png at all, but long enough")
        with self.assertRaises(self.mod.BuildError):
            self.mod.load_card_bytes(
                not_png,
                expected_sha256=hashlib.sha256(
                    b"GIF89a not a png at all, but long enough").hexdigest())


class DraftRootTypeTests(unittest.TestCase):
    """Round-4 note 3: Browse ('plus N library specifications') and the
    documents index call every root document a library specification, so a
    root document of another type must fail the draft build.
    render_draft_variant reads TAXONOMY; the test points it at a doctored
    copy and restores it."""

    @classmethod
    def setUpClass(cls):
        cls.mod = _load_build()

    def test_a_root_document_that_is_not_a_specification_fails(self):
        mod = self.mod
        figures = mod.compute_figures()
        text = mod.TAXONOMY.read_text(encoding="utf-8")
        doctored_text, n = re.subn(
            r'(- path: "([^"]*)"\n  domain: "root"\n  type: )"Specification"',
            r'\1"Guide"', text, count=1)
        self.assertEqual(n, 1, "no root Specification block in taxonomy.yml")
        path = re.search(r'- path: "([^"]*)"\n  domain: "root"\n  type: '
                         r'"Guide"', doctored_text).group(1)
        root = Path(tempfile.mkdtemp(prefix="draft-taxonomy-"))
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        doctored = root / "taxonomy.yml"
        doctored.write_text(doctored_text, encoding="utf-8")
        draft = next(v for v in mod.VARIANTS if v.draft_rules)
        original = mod.TAXONOMY
        mod.TAXONOMY = doctored
        try:
            with self.assertRaisesRegex(
                    mod.BuildError,
                    re.escape(f"root document {path} has type 'Guide', "
                              "not Specification")):
                mod.render_variant(figures, draft)
        finally:
            mod.TAXONOMY = original


class DraftTemplateTypedCountTests(unittest.TestCase):
    """Round-2 fix 1: no draft template may type a count. Every number a page
    shows is computed at build time (owner decision), so a digit may appear in
    a template source only inside one of the listed exceptions."""

    # The exceptions, each a regex blanked from the source before the digit
    # scan; any digit that survives is a typed count and fails the test.
    EXCEPTIONS = (
        # The light and dark switch's two inline SVG glyphs, the moon and the
        # sun, exactly as the switch renders them (SCHEME_SWITCH, baseline
        # 1.6.1 section 7.33, copied from the reference pages): drawing sizes
        # and coordinates, not counts. Any other inline SVG is scanned. First,
        # so the class blanking below cannot break the literal match.
        *(re.escape(glyph) for glyph in re.findall(
            r'<svg class="(?:moon|sun)" .*?</svg>', SCHEME_SWITCH)),
        # A {{PLACEHOLDER}}: the computed values.
        r"\{\{[A-Z0-9_]+\}\}",
        # A URL in an href or src attribute.
        r'(?:href|src)="[^"]*"',
        # Structural id and class attribute values (anchor ids like d-1 and
        # the shared footer's slice-6 grid classes are positions, not counts).
        r'(?:id|class)="[^"]*"',
        # A tabindex value (the crosswalk's keyboard-focusable .tablewrap
        # scroll region): a focus position, not a count.
        r'tabindex="[^"]*"',
        # HTML heading tag names (h1, h2).
        r"</?h[1-6]\b",
        # The charset and viewport meta attribute values.
        r'(?:charset|content)="[^"]*"',
        # A licence version string: CC BY-SA 4.0, CC0 1.0, OFL 1.1 (the
        # template version is {{BASELINE_VERSION}}, from the pin).
        r"\d+(?:\.\d+)+",
        r"\bCC0\b",
        # A licence clause reference: 2(a)(1), 3(a)(1)(A), section 5.
        r"\b\d+(?:\([A-Za-z0-9]+\))+",
        r"\b[Ss]ection \d+\b",
        # The licence's own cure period, quoted from LICENSE section 6(b)(1).
        r"\b30 days\b",
        # The search page's example query names a standard edition.
        r"\bISO 27001\b",
        # The error page names its HTTP status.
        r"\b404\b",
        # The disclosure page's ordinal entry labels (positions, not counts).
        r"\bEntry \d+\b",
        # The shared family footer's fixed site-list label: the baseline
        # owns that wording, outside this site's copy.
        r'aria-label="The 7 project sites"',
        # The contributors page's carried-over prose (the old About page's
        # contributor content, maintainer decision 2026-11-04 item 3): a
        # decade written as prose and a contributor's GitHub handle, neither
        # a corpus count.
        r"\bthe early 2000s\b",
        r"\b0xbja\b",
    )

    def _typed_number(self, text):
        """The first digit run left once every exception is blanked."""
        for pattern in self.EXCEPTIONS:
            text = re.sub(pattern, " ", text)
        return re.search(r"\d+", text), text

    def test_only_the_switch_glyphs_are_exempt(self):
        """Round 2 NOTE 5: the SVG exception blanks the switch's own moon
        and sun glyphs and nothing else, so a typed count inside any other
        inline SVG still fails the scan."""
        glyphs = re.findall(r'<svg class="(?:moon|sun)" .*?</svg>',
                            SCHEME_SWITCH)
        self.assertEqual(len(glyphs), 2, "the switch's two glyphs")
        match, _ = self._typed_number(SCHEME_SWITCH)
        self.assertIsNone(match, "a switch glyph is not exempt")
        for svg in ('<svg class="badge"><text>358 documents</text></svg>',
                    '<svg class="moon"><text>358 documents</text></svg>'):
            match, _ = self._typed_number(svg)
            self.assertIsNotNone(match, f"an inline SVG is exempt: {svg}")
            self.assertEqual(match.group(0), "358")

    def test_no_typed_count_in_any_draft_template(self):
        template_root = REPO_ROOT / ".web" / "templates-draft"
        sources = sorted(template_root.rglob("*.html"))
        self.assertTrue(sources, "no draft template sources found")
        for path in sources:
            if path.name == "for-ai.html":
                # The carried-over For-AI page (maintainer decision
                # 2026-11-04 item 4) types standard editions, statute
                # numbers and memo numbers by design; its OWASP and EU AI
                # Act edition lines are governed by the stale-editions
                # check in build.py --check, not by the typed-count rule,
                # and none of its numbers is a corpus count.
                continue
            match, text = self._typed_number(
                path.read_text(encoding="utf-8"))
            if match:
                start = max(0, match.start() - 60)
                context = text[start:match.end() + 60].replace("\n", " ")
                self.fail(
                    f"{path.relative_to(REPO_ROOT)}: typed number "
                    f"{match.group(0)!r} outside the listed exceptions "
                    f"(counts are computed at build time, never typed): "
                    f"...{context}..."
                )


class SiteB5FixTests(unittest.TestCase):
    """42: Site review batch B5 (triage 2026-11-05): cross-site wording and
    counts, one test per confirmed finding, each failing without its fix on
    the rendered pages."""

    @classmethod
    def setUpClass(cls):
        cls.mod = _load_build()
        cls.figures = cls.mod.compute_figures()
        cls.draft_variant = next(
            v for v in cls.mod.VARIANTS if v.draft_rules
        )
        rendered = cls.mod.render_variant(cls.figures, cls.draft_variant)
        cls.draft_html = {
            cls.mod.output_rel_for(cls.draft_variant, rel): content
            for rel, content in rendered
            if cls.mod.output_rel_for(cls.draft_variant, rel)
            .endswith(".html")
        }

    def _taxonomy_by_path(self):
        return {d["path"]: d for d in self.mod.parse_taxonomy_full(
            self.mod.TAXONOMY.read_text(encoding="utf-8"))}

    def test_f08_index_and_search_define_area_against_domain(self):
        """F08: sitewide prose counts domains while the index and the search
        page count areas; each page that says areas ties the word to the
        domains once."""
        index = self.draft_html["documents/index.html"]
        self.assertIn(" areas, ", index)
        self.assertIn("An area here is a corpus domain.", index)
        search = self.draft_html["search/index.html"]
        self.assertIn(
            "A corpus document's area is its domain; an adopter document's "
            "area is docs/.", search)

    def test_f09_browse_lists_every_instrument_with_both_counts(self):
        """F09: the By instrument heading sat over a lone sentence with no
        list, its count never squared with the instrument pages. The section
        lists every configured instrument, each link opening a rendered
        page, and its sentence carries both generated counts."""
        browse = self.draft_html["browse/index.html"]
        block = re.search(
            r'<h2 id="instruments">By instrument</h2>.*?'
            r'<ul class="plan three">(.*?)</ul>', browse, re.S)
        self.assertIsNotNone(block, "Browse has no By instrument list")
        hrefs = _HREF_RE.findall(block.group(1))
        self.assertEqual(
            hrefs,
            [f"/crosswalk/{inst.key}/"
             for inst in self.mod.CROSSWALK_INSTRUMENTS],
            "one row per configured instrument, in configured order")
        for href in hrefs:
            self.assertIn(_page_rel_for(href), self.draft_html, href)
        main = len([i for i in self.mod.CROSSWALK_INSTRUMENTS
                    if i.main_table])
        total = len(self.mod.CROSSWALK_INSTRUMENTS)
        self.assertNotEqual(main, total,
                            "the finding's shape: the two counts differ")
        self.assertIn(
            f"against {main} standards, laws, frameworks, and programmes "
            "in its full table", browse)
        self.assertIn(f"the {total} instrument pages", browse)

    def test_f11_scope_pointers_and_fallback_sort(self):
        """F11: the index/search scope reconciliation lived on Browse alone.
        All Documents points at the adopter documents it leaves out; the
        search page says the library specifications have no row and that
        the no-JS list runs newest first, checked on the rendered rows."""
        index = self.draft_html["documents/index.html"]
        self.assertIn('href="/browse/#adopter-documents"', index)
        search = self.draft_html["search/index.html"]
        root = [d for d in self._taxonomy_by_path().values()
                if d.get("domain") == self.mod.ROOT_DOMAIN]
        self.assertTrue(root, "the finding's shape: root specifications")
        self.assertIn(
            f"The {len(root)} library specifications, read on GitHub, have "
            "no row here.", search)
        self.assertIn(
            "Without script, the whole list stays below, newest first.",
            search)
        scope = re.search(r"<ul[^>]* data-search-scope>(.*?)</ul>", search,
                          re.S).group(1)
        dates = re.findall(r"<small>([0-9-]+)</small>", scope)
        self.assertTrue(dates)
        self.assertEqual(dates, sorted(dates, reverse=True),
                         "the no-JS list runs newest first")

    def test_f12_landing_crosswalk_tile_scopes_its_count(self):
        """F12: the home tile's instrument count is the full table's, true
        only with the qualifier; the tile says so."""
        landing = self.draft_html["index.html"]
        count = len([i for i in self.mod.CROSSWALK_INSTRUMENTS
                     if i.main_table])
        self.assertIn(
            f"The corpus domains set against {count} standards, laws, "
            "frameworks, and programmes in the full table", landing)

    def test_f24_landing_example_card_names_its_document(self):
        """F24: the Open a document card never named its target. The card
        description opens with the example document's taxonomy title."""
        landing = self.draft_html["index.html"]
        title = self._taxonomy_by_path()[
            self.mod.DRAFT_EXAMPLE_DOC]["title"]
        card = re.search(
            r'<span class="t">Open a document</span>'
            r'<span class="n">example</span><span class="d">([^<]*)</span>',
            landing)
        self.assertIsNotNone(card, "the example card is on the landing page")
        self.assertTrue(
            unescape(card.group(1)).startswith(f"{title}: "),
            "the card description opens with the example document's title")

    def test_f25_landing_glosses_the_rule_pack(self):
        """F25: "governance rule pack" appeared without introduction. The
        AIQT note glosses it in place."""
        landing = self.draft_html["index.html"]
        self.assertIn(
            "The library's governance rule pack, the automated contribution "
            "rules an AI assistant follows, is now the", landing)

    def test_f27_browse_reconciles_the_specification_count(self):
        """F27: the Browse meta's library specifications and the By type
        Specification row read as a contradiction. The scope line splits
        the row's count, with the recomputed numbers."""
        browse = self.draft_html["browse/index.html"]
        spec_total = dict(self.figures["types"]).get("Specification", 0)
        root = self.figures["root_count"]
        self.assertGreater(spec_total, root,
                           "the finding's shape: domain specifications")
        self.assertIn(
            f"Of the Specification row's {spec_total}, {spec_total - root} "
            f"sit in the domains and {root} are the library specifications.",
            browse)

    def test_f36_index_filter_mechanics_sit_in_a_details_block(self):
        """F36: 1,296 characters of filter mechanics stood in body copy. The
        body keeps one short usage paragraph; the mechanics sit in a
        collapsed details element, no claim dropped."""
        index = self.draft_html["documents/index.html"]
        self.assertIn("<details><summary>How the filters behave</summary>",
                      index)
        body = re.search(r"<p>With script, ([^<]*)</p>", index)
        self.assertIsNotNone(body)
        self.assertLess(len(body.group(1)), 300,
                        "the body usage paragraph stays short")
        for kept in ("match every word;",
                     "marked unavailable: it is greyed out, with its word "
                     "struck through and its count at zero",
                     "All and a chosen chip are never unavailable."):
            self.assertIn(kept, index, "no mechanics claim is dropped")

    def test_f40_govern_type_clauses_read_generic_singular(self):
        """F40: "roadmaps stage it" overstated a type holding one corpus
        document. Each configured clause reads as the type's role, generic
        singular, and the rendered sentence carries the clauses."""
        html = self.draft_html["govern/index.html"]
        roles = self.mod.DRAFT_GOVERN_LANDING_TYPES
        for type_name, clause in roles.items():
            self.assertTrue(clause.startswith(("a ", "an ")),
                            f"{type_name}: the clause is generic singular")
        self.assertIn(
            f"The work rests on {len(roles)} document types: "
            + self.mod._draft_series(roles.values()) + ".", html)

    def test_f41_policies_name_the_domains_without_a_policy(self):
        """F41: domains outside the subject list had no pointer to where
        their governing intent lives. The page names exactly the domains
        with no policy or template; review round 2 item 4: the sentence
        states only what the taxonomy shows (a Related Documents entry
        naming a policy), never an unchecked reliance claim."""
        html = self.draft_html["policies/index.html"]
        types = {tp["type"]: tp for tp in self.figures["type_pages"]}
        covered = {d["domain"]
                   for type_name in ("Policy", "Template")
                   for d in types[type_name]["docs"]
                   if d["domain"] != self.mod.ROOT_DOMAIN}
        missing = [domain for domain, _ in self.figures["domains"]
                   if domain not in covered]
        self.assertGreater(len(missing), 1,
                           "the finding's shape: uncovered domains")
        full = self.mod.parse_taxonomy_full(
            self.mod.TAXONOMY.read_text(encoding="utf-8"))
        naming = [domain for domain in missing
                  if any(rp.rpartition("/")[2].startswith("policy-")
                         for d in full if d.get("domain") == domain
                         for rp in d.get("related_documents", ()))]
        self.assertEqual(naming, missing,
                         "today every uncovered domain names policies")
        labels = self.mod._draft_series(
            self.mod.draft_domain_label(d) for d in missing)
        self.assertIn(
            "<p>" + self.mod._esc(
                f"{labels} publish no policy or template of their own; "
                "documents in each name the policies of other domains "
                "among their related documents, and each domain page "
                "lists what the domain carries.") + "</p>", html)
        self.assertNotIn("rely on the overarching", html)

    def test_f45_landing_start_list_carries_an_obligation_card(self):
        """F45: home reached no need path. The Start here list carries a
        Meet an obligation card opening /comply/ and naming the other need
        paths by their card titles."""
        landing = self.draft_html["index.html"]
        main = landing.split('<main id="main-content">', 1)[1]
        card = re.search(
            r'<li><a href="/comply/"><span class="t">Meet an obligation'
            r'</span><span class="n">([^<]*)</span>'
            r'<span class="d">([^<]*)</span></a></li>', main)
        self.assertIsNotNone(card, "the obligation card is on the landing "
                             "page")
        for title, _, _, _ in self.mod.DRAFT_NEEDS:
            if title != "Meet an obligation":
                self.assertIn(title, card.group(2),
                              "the card names the other need paths")


class SiteB8FixTests(unittest.TestCase):
    """47: Site review batch B8 (three NOTE findings): the decision
    narratives index takes its kind's name, the domain pages label their
    tour steps, and every trade programme page renders the shared
    control-area table; one test per finding, each failing without its fix
    on the rendered pages."""

    @classmethod
    def setUpClass(cls):
        cls.mod = _load_build()
        cls.figures = cls.mod.compute_figures()
        cls.draft_variant = next(
            v for v in cls.mod.VARIANTS if v.draft_rules
        )
        rendered = cls.mod.render_variant(cls.figures, cls.draft_variant)
        cls.draft_html = {
            cls.mod.output_rel_for(cls.draft_variant, rel): content
            for rel, content in rendered
            if cls.mod.output_rel_for(cls.draft_variant, rel)
            .endswith(".html")
        }

    def test_f16_decision_narratives_index_takes_its_kinds_name(self):
        """F16: the decision narratives index sat at /decide/choices/, a
        third name beside its heading and its reading-room segment. Every
        kind's index slug is its heading in kebab case, at most a leading
        qualifier dropped, and ends its pages' reading-room segment; the old
        address renders nothing and no page links it."""
        mod = self.mod
        with self.subTest(check="the old address renders nothing"):
            self.assertNotIn("decide/choices/index.html", self.draft_html)
        with self.subTest(check="no page links the old address"):
            self.assertEqual(
                sorted(rel for rel, html in self.draft_html.items()
                       if "/decide/choices" in html), [])
        segments = {}
        for page in self.figures["narratives"]:
            segments.setdefault(page["narrative_type"], set()).add(
                page["route"].split("/")[1])
        for narrative_type, (slug, label, _) in (
                mod.DRAFT_NARRATIVE_SUBTYPES.items()):
            with self.subTest(kind=narrative_type):
                self.assertTrue(
                    label.lower().replace(" ", "-").endswith(slug),
                    f"{slug}: not its heading {label!r} in kebab case")
                self.assertTrue(segments.get(narrative_type), narrative_type)
                for segment in segments[narrative_type]:
                    self.assertTrue(segment.endswith(slug),
                                    f"{slug}: not the end of /decisions/"
                                    f"{segment}/")
        self.assertEqual(
            mod.DRAFT_NARRATIVE_SUBTYPES["Decision Narrative"][0],
            "decision-narratives")
        index = self.draft_html["decide/decision-narratives/index.html"]
        self.assertIn("<h1>Decision narratives</h1>", index)
        for rel in ("decide/index.html", "browse/index.html"):
            self.assertIn('href="/decide/decision-narratives/"',
                          self.draft_html[rel], rel)

    def test_f29_domain_pages_label_their_tour_steps(self):
        """F29: each domain page's Next is the next stop of the site tour,
        and the last domain's jump to a document read as unrelated. Every
        domain page labels the link "Next on the tour"; the order is
        unchanged: Browse opens the first domain, each domain the next, and
        the last the example document."""
        mod = self.mod
        seq = [dp["domain"] for dp in self.figures["domain_pages"]]
        self.assertGreater(len(seq), 1)
        browse = self.draft_html["browse/index.html"]
        self.assertIn(
            f'<a class="start" href="/{seq[0]}/">Open a domain: '
            f"{mod._esc(mod.draft_domain_label(seq[0]))} <span", browse)
        title = next(
            d["title"] for d in mod.parse_taxonomy_full(
                mod.TAXONOMY.read_text(encoding="utf-8"))
            if d["path"] == mod.DRAFT_EXAMPLE_DOC)
        for idx, domain in enumerate(seq):
            if idx + 1 < len(seq):
                href = f"/{seq[idx + 1]}/"
                text = "Open a domain: " + mod._esc(
                    mod.draft_domain_label(seq[idx + 1]))
            else:
                href = mod._doc_page_url("", mod.DRAFT_EXAMPLE_DOC)
                text = "Open a document: " + mod._esc(title)
            with self.subTest(domain=domain):
                self.assertIn(
                    '<div class="next"><p class="lbl">Next on the tour</p>'
                    f'<a class="start" href="{href}">{text} <span',
                    self.draft_html[f"{domain}/index.html"])

    def test_f34_trade_programme_pages_render_the_shared_table(self):
        """F34: /crosswalk/aeo/ said its control-area table is rendered on
        the CTPAT page. Every programme page the combined section covers
        carries the section's table, with a sentence naming the section,
        and the CTPAT page keeps its own sentence."""
        mod = self.mod
        heading = mod.CROSSWALK_BY_KEY["ctpat"].reverse_section
        rows = mod.parse_reverse_matrix(mod.CROSSWALK_REVERSE_MATRIX.read_text(
            encoding="utf-8"))[heading]["rows"]
        table_re = re.compile(
            r'<h2 id="control-areas">[^<]*</h2>\n<p>(.*?)</p>\n'
            r'<div class="wide">.*?(<tbody>.*?</tbody>)', re.S)
        ctpat = table_re.search(self.draft_html["crosswalk/ctpat/index.html"])
        self.assertRegex(
            ctpat.group(1),
            r"\AFrom the <a [^>]*>.*?</a>, which answers: given a control "
            r"identifier or family, which documents address it\.\Z")
        self.assertEqual(ctpat.group(2).count("<tr>"), len(rows))
        covered = [i.key for i in mod.CROSSWALK_INSTRUMENTS
                   if i.reverse_pointer == "ctpat"]
        self.assertIn("aeo", covered)
        for key in covered:
            with self.subTest(instrument=key):
                found = table_re.search(
                    self.draft_html[f"crosswalk/{key}/index.html"])
                self.assertIsNotNone(found, f"{key}: no control-area table")
                # Review of 50b453ea3 NOTE: two plain sentences, no colon
                # clause inside the naming sentence.
                self.assertRegex(
                    found.group(1),
                    r"\AThe <a [^>]*>.*?</a> answers which documents address "
                    r"a given control identifier or family\. It names this "
                    r"programme in its combined section &quot;"
                    + re.escape(mod._esc(heading))
                    + r"&quot;\. The table is that whole section, the same "
                    r'one the <a href="/crosswalk/ctpat/">[^<]*</a> '
                    r"instrument page shows\.\Z")
                self.assertEqual(found.group(2), ctpat.group(2))

    def test_trade_programme_pages_keep_the_reverse_crosswalk_anchor(self):
        """Review of 50b453ea3: the BASC, PIP, WCO SAFE and AEO pages lost
        their old id="reverse-crosswalk" anchor, so an outside link to it
        landed at the top. The shared table's section label carries that
        id again, once, right above the section heading; the CTPAT page,
        which never had the anchor, has none."""
        mod = self.mod
        covered = [i.key for i in mod.CROSSWALK_INSTRUMENTS
                   if i.reverse_pointer == "ctpat"]
        self.assertEqual(set(covered), {"basc", "pip", "wco-safe", "aeo"})
        label_re = re.compile(
            r'<p class="lbl sec" id="reverse-crosswalk">Mapped control '
            r'areas, \d+</p>\n<h2 id="control-areas">')
        for key in covered:
            with self.subTest(instrument=key):
                page = self.draft_html[f"crosswalk/{key}/index.html"]
                self.assertEqual(page.count('id="reverse-crosswalk"'), 1)
                self.assertRegex(page, label_re)
        self.assertNotIn('id="reverse-crosswalk"',
                         self.draft_html["crosswalk/ctpat/index.html"])


class DraftTestSectionNumberTests(unittest.TestCase):
    """Round-1 NOTE: two test sections both said 8. Each numbered section
    comment carries its own number from the module docstring's list. Round 2
    WARN 2: a class docstring's leading section number ("25: ...") names a
    docstring item too, and the item whose words it uses."""

    # Words too common to tie a docstring to one item.
    COMMON = frozenset(
        "a an and as at by each every for from has in is it its no not of on "
        "or so that the their to was where which while with".split())

    def test_section_comments_follow_the_module_docstring(self):
        items = re.findall(r"^(\d+)\. ", __doc__, re.M)
        source = Path(__file__).read_text(encoding="utf-8")
        sections = re.findall(r"^    # -- (\d+)\. ", source, re.M)
        self.assertTrue(sections, "no numbered section comments found")
        self.assertEqual(len(sections), len(set(sections)),
                         f"two sections share a number: {sections}")
        self.assertLessEqual(set(sections), set(items),
                             "a section number names no docstring item")

    def _phrases(self, text):
        """Adjacent pairs of uncommon words, possessives dropped."""
        words = re.findall(r"[a-z0-9][a-z0-9.-]*[a-z0-9]|[a-z]",
                           text.lower().replace("'s", ""))
        return {(a, b) for a, b in zip(words, words[1:])
                if a not in self.COMMON and b not in self.COMMON}

    # A class docstring's leading numbers: "25: ", "18 and 21: ", "29 to 31: "
    # or "4, 5 and 6: " (batch 3 note: "N and M:" was skipped unchecked).
    _LEAD_RE = re.compile(r"(\d+(?:(?:, | and | to )\d+)*): ")

    @classmethod
    def _lead_numbers(cls, doc):
        """The item numbers a docstring's lead names, a range expanded, or
        None when it has no numbered lead."""
        match = cls._LEAD_RE.match(doc)
        if not match:
            return None, None
        numbers = []
        for part in re.split(r", | and ", match.group(1)):
            low, _, high = part.partition(" to ")
            numbers += [str(n) for n in range(int(low), int(high or low) + 1)]
        return numbers, match.end()

    def _docstring_number_faults(self, classes):
        """Every fault in the classes' numbered docstrings: a number that
        names no module docstring item, and a docstring whose two-word
        phrases, held by exactly one item each, belong to items none of its
        numbers names."""
        items = dict(re.findall(r"^(\d+)\. (.*?)(?=^\d+\. |\Z)", __doc__,
                                re.M | re.S))
        phrases = {number: self._phrases(text)
                   for number, text in items.items()}
        faults = []
        numbered = 0
        for name, obj in classes:
            doc = inspect.cleandoc(obj.__doc__ or "")
            numbers, end = self._lead_numbers(doc)
            if numbers is None:
                continue
            numbered += 1
            for number in numbers:
                if number not in items:
                    faults.append(f"{name}: docstring number {number} names "
                                  "no docstring item")
            owners = set()
            for pair in self._phrases(doc[end:]):
                holders = [owner for owner, held in phrases.items()
                           if pair in held]
                if len(holders) == 1:
                    owners.update(holders)
            if owners and not owners & set(numbers):
                faults.append(f"{name}: docstring says {', '.join(numbers)} "
                              f"but its phrases belong to item(s) "
                              f"{sorted(owners)}")
        return numbered, faults

    def test_docstring_numbers_follow_the_module_docstring(self):
        """A class docstring's numbers name docstring items, and when the
        docstring shares a two-word phrase with exactly one item, one of its
        own items is among those (the palette gate class said 24 while only
        item 25 names the palette gate). A lead naming several items ("18
        and 21: ", "29 to 31: ") is checked number by number."""
        classes = [(name, obj) for name, obj in sorted(globals().items())
                   if inspect.isclass(obj) and obj.__module__ == __name__]
        numbered, faults = self._docstring_number_faults(classes)
        self.assertTrue(numbered, "no numbered class docstrings found")
        self.assertEqual(faults, [])
        multi = [name for name, obj in classes
                 if len(self._lead_numbers(
                     inspect.cleandoc(obj.__doc__ or ""))[0] or ()) > 1]
        self.assertTrue(multi, "a class docstring names several items today")

    def test_docstring_guard_parses_a_lead_naming_several_items(self):
        """Batch 3 (batch 2 note): the guard read only a "N: " lead, so a
        docstring opening "N and M: " was skipped and a number in it naming
        no item passed. On fixtures: each number of an "and" lead and of a
        "to" range must name an item, and a lead whose numbers all name
        items passes."""
        items = re.findall(r"^(\d+)\. ", __doc__, re.M)
        top = max(int(n) for n in items)
        good = type("Good", (), {"__doc__": f"1 and {top}: fixture."})
        bad_and = type("BadAnd", (), {"__doc__": f"1 and {top + 1}: fixture."})
        bad_range = type("BadRange", (),
                         {"__doc__": f"{top - 1} to {top + 1}: fixture."})
        self.assertEqual(self._lead_numbers("18 and 21: x")[0], ["18", "21"])
        self.assertEqual(self._lead_numbers("29 to 31: x")[0],
                         ["29", "30", "31"])
        self.assertEqual(self._lead_numbers("4, 5 and 6: x")[0],
                         ["4", "5", "6"])
        _, faults = self._docstring_number_faults([("Good", good)])
        self.assertEqual(faults, [])
        _, faults = self._docstring_number_faults(
            [("BadAnd", bad_and), ("BadRange", bad_range)])
        self.assertEqual(
            faults,
            [f"BadAnd: docstring number {top + 1} names no docstring item",
             f"BadRange: docstring number {top + 1} names no docstring item"])


class PromotedRouteCoverageTests(unittest.TestCase):
    """The durable promotion route-coverage pin (draft-site promotion,
    maintainer decisions 2026-11-04), replacing the retired frozen-root
    byte-identity test: every URL the pre-promotion live root served (the 33
    sitemap URLs plus the error page and the root files, each pinned below
    as a literal, never derived) must resolve to a rendered output of the
    promoted site or redirect, in one hop through the emitted ``_redirects``,
    to a rendered output or an allow-listed external URL; and every
    pre-promotion /draft/ path (the inventory main 716a3f53b rendered,
    pinned as literals in tests/fixtures/pre-promotion-draft-inventory.txt)
    must map through the splat rule to an existing output."""

    # The pre-promotion live root inventory, pinned as literals: the 33
    # sitemap URLs (the 4 fixed pages, 12 domain pages, 17 type pages) plus
    # 404.html and the root files. /about/, /pack/ and /for-ai/ are the three
    # retired-or-carried fixed pages of the old root.
    PRE_PROMOTION_URLS = (
        "/", "/about/", "/pack/", "/for-ai/",
        "/ai/", "/privacy/", "/security/", "/governance/", "/compliance/",
        "/crypto/", "/operations/", "/resilience/", "/supply-chain/",
        "/dev-security/", "/risk/", "/architecture/",
        "/types/annex/", "/types/charter/", "/types/checklist/",
        "/types/framework/", "/types/guide/", "/types/guideline/",
        "/types/matrix/", "/types/plan/", "/types/policy/",
        "/types/principle/", "/types/procedure/", "/types/register/",
        "/types/roadmap/", "/types/sop/", "/types/specification/",
        "/types/standard/", "/types/template/",
        "/404.html", "/robots.txt", "/sitemap.xml", "/llms.txt",
        "/_headers", "/.well-known/security.txt",
    )
    # External redirect targets the coverage pin accepts (maintainer
    # decision 2026-11-04 item 2: /pack/ goes to the AIQT project).
    ALLOWED_EXTERNAL = frozenset({"https://aiqt.ai/"})

    @classmethod
    def setUpClass(cls):
        cls.mod = _load_build()
        cls.figures = cls.mod.compute_figures()
        cls.site_pages = cls.mod.render_site(cls.figures)
        cls.outputs = {rel for rel, _ in cls.site_pages}
        redirects = [c for rel, c in cls.site_pages if rel == "_redirects"]
        assert len(redirects) == 1
        cls.rules = []
        for line in redirects[0].splitlines():
            src, dst, status = line.split(" ")
            cls.rules.append((src, dst, status))

    def _lookup(self, url):
        """The rendered output a site URL serves, or None."""
        rel = _page_rel_for(url)
        return rel if rel in self.outputs else None

    def _resolve(self, url):
        """The rendered output or allow-listed external URL ``url`` reaches,
        directly or through at most one _redirects hop; None if it 404s."""
        for src, dst, status in self.rules:
            if src.endswith("/*") and url.startswith(src[:-1]):
                self.assertEqual(status, "301", src)
                target = dst.replace(":splat", url[len(src) - 1:])
                return self._lookup(target)
            if url == src:
                self.assertEqual(status, "301", src)
                if dst in self.ALLOWED_EXTERNAL:
                    return dst
                self.assertFalse(dst.startswith("http"),
                                 f"{src}: external target {dst} is not "
                                 "allow-listed")
                return self._lookup(dst)
        return self._lookup(url)

    def test_redirect_rules_are_exactly_the_decided_rules(self):
        # The three promotion rules plus the round-2 fix 7 spellings: the
        # slashless and index.html forms of the two redirected addresses,
        # and /draft itself (the /draft/* splat does not match it). Item
        # 3b788 adds the /licence/ spelling (the page prose spells
        # "Licence", the route is /license/) in the same three forms. Site
        # review F16 adds the moved /decide/choices/ index in the same three
        # forms, and its /draft/ address ahead of the splat.
        self.assertEqual(self.rules, [
            ("/draft/decide/choices/", "/decide/decision-narratives/", "301"),
            ("/draft/decide/choices", "/decide/decision-narratives/", "301"),
            ("/draft/decide/choices/index.html",
             "/decide/decision-narratives/", "301"),
            ("/draft/*", "/:splat", "301"),
            ("/draft", "/", "301"),
            ("/about/", "/contributors/", "301"),
            ("/about", "/contributors/", "301"),
            ("/about/index.html", "/contributors/", "301"),
            ("/licence/", "/license/", "301"),
            ("/licence", "/license/", "301"),
            ("/licence/index.html", "/license/", "301"),
            ("/decide/choices/", "/decide/decision-narratives/", "301"),
            ("/decide/choices", "/decide/decision-narratives/", "301"),
            ("/decide/choices/index.html", "/decide/decision-narratives/",
             "301"),
            ("/pack/", "https://aiqt.ai/", "301"),
            ("/pack", "https://aiqt.ai/", "301"),
            ("/pack/index.html", "https://aiqt.ai/", "301"),
        ])

    def test_every_pre_promotion_root_url_resolves_or_redirects(self):
        for url in self.PRE_PROMOTION_URLS:
            with self.subTest(url=url):
                self.assertIsNotNone(
                    self._resolve(url),
                    f"{url}: served by the old root, resolves to nothing on "
                    "the promoted site")
        # The two redirect-only addresses land where the maintainer decided.
        self.assertEqual(self._resolve("/about/"), "contributors/index.html")
        self.assertEqual(self._resolve("/pack/"), "https://aiqt.ai/")
        # Item 3b788: the Canadian spelling lands on the licence page.
        self.assertEqual(self._resolve("/licence/"), "license/index.html")
        # The carried-over page serves directly, not via a redirect.
        self.assertEqual(self._lookup("/for-ai/"), "for-ai/index.html")

    def test_slashless_index_html_and_bare_draft_forms_redirect(self):
        # Round-2 fix 7: the alternate spellings land where their canonical
        # addresses do, each in one 301 hop.
        self.assertEqual(self._resolve("/about"), "contributors/index.html")
        self.assertEqual(self._resolve("/about/index.html"),
                         "contributors/index.html")
        self.assertEqual(self._resolve("/pack"), "https://aiqt.ai/")
        self.assertEqual(self._resolve("/pack/index.html"),
                         "https://aiqt.ai/")
        self.assertEqual(self._resolve("/draft"), "index.html")

    def test_f16_old_decision_narratives_addresses_redirect(self):
        # Site review F16: every spelling of the old /decide/choices/ index,
        # and of its /draft/ form, lands on the renamed index in one 301
        # hop; the sitemap lists the new address and not the old.
        new = "decide/decision-narratives/index.html"
        sitemap = [c for rel, c in self.site_pages if rel == "sitemap.xml"][0]
        with self.subTest(check="the old address renders nothing"):
            self.assertNotIn("decide/choices/index.html", self.outputs)
        with self.subTest(check="the sitemap drops the old address"):
            self.assertNotIn("/decide/choices", sitemap)
        self.assertIn(new, self.outputs)
        self.assertIn("<loc>https://grclibrary.ai/decide/decision-narratives/"
                      "</loc>", sitemap)
        for old in ("/decide/choices/", "/decide/choices",
                    "/decide/choices/index.html", "/draft/decide/choices/",
                    "/draft/decide/choices",
                    "/draft/decide/choices/index.html"):
            with self.subTest(url=old):
                self.assertEqual(self._resolve(old), new)

    # The pinned pre-promotion /draft/ output inventory (round-2 fix 6):
    # every dist-relative output path main 716a3f53b's own .web/build.py
    # rendered for the draft tree, stored as fixture literals, never derived
    # from the promoted render.
    DRAFT_INVENTORY = (REPO_ROOT / "tests" / "fixtures"
                       / "pre-promotion-draft-inventory.txt")
    # Pinned draft pages whose promoted page moved after promotion, each
    # reached in one hop by its own rule ahead of the splat (site review
    # F16: the decision narratives index left /decide/choices/).
    MOVED = {"draft/decide/choices/index.html":
             "decide/decision-narratives/index.html"}

    def test_every_pre_promotion_draft_path_maps_through_the_splat(self):
        inventory = [
            line
            for line in self.DRAFT_INVENTORY.read_text(
                encoding="utf-8").splitlines()
            if line and not line.startswith("#")
        ]
        # The whole pinned tree: 494 pages and files plus the 37 copied
        # baseline assets of the pre-promotion draft render.
        self.assertEqual(len(inventory), 531)
        self.assertEqual(len(inventory), len(set(inventory)))
        self.assertLessEqual(set(self.MOVED), set(inventory))
        for out_rel in inventory:
            self.assertTrue(out_rel.startswith("draft/"), out_rel)
            promoted_rel = self.MOVED.get(out_rel, out_rel[len("draft/"):])
            if out_rel.endswith("/index.html"):
                old_url = "/" + out_rel[: -len("index.html")]
            else:
                old_url = "/" + out_rel
            with self.subTest(url=old_url):
                self.assertEqual(
                    self._resolve(old_url), promoted_rel,
                    f"{old_url}: the pre-promotion draft address must map "
                    "through the splat to its promoted output")
            # The explicit file spelling resolves through the splat too.
            with self.subTest(url="/" + out_rel):
                self.assertEqual(self._resolve("/" + out_rel), promoted_rel)


class ProgrammeClaimsTests(unittest.TestCase):
    """The programme-claims PR (on main d6565f5e7): the BASC, PIP, NEEC and
    UK AEO-S relationship claims that finding WCO-SWEEP-REST-0507 held
    back, checked against the held texts by a research pass, and the small
    fixes routed to it by review round 6 of PR #3103 and by the per-touch
    reference audit. Held paths are under the reference corpus; line numbers
    are those of the held full-text extracts, counting only LF as a line end
    (the repository's convention for held extracts, as in
    tools/audit-reference-breadth.py), so a form feed or a Unicode line
    separator inside a line does not start a new one.

    The class has 72 tests: 62 corpus regression tests, 5 self-checks and
    5 held-source consistency checks.

    The corpus regression tests read the corpus files directly (no site
    render) and are written to fail when their fix is reverted. The
    exact-row pins (_OEA_ROW, _NEEC_GLOSSARY, _BASC_ANNEX_CLAIM and the like)
    are editorial snapshots: they catch reverted wording, not a wrong
    reading. The class-wide negative guards over every .md line catch a
    removed claim wherever it comes back.

    The self-checks are the tests in _SELF_CHECKS. They read no corpus file
    or held extract: four hold the class-wide guards' matchers to planted
    sentences each must catch or let through, and one holds this docstring
    to the class. Reverting a corpus correction cannot make them fail;
    loosening a guard's matcher or miscounting the class does.

    The held-source consistency checks are the tests in _HELD_SOURCE_CHECKS.
    They read the held extracts or the reference catalogue, so they run
    only when the reference corpus is present (GRC_REF_PATH or a sibling
    grc_library_ref checkout) and skip without it; CI holds no reference
    corpus, so they run locally only. Three of them read only the
    extracts, so reverting a corpus correction cannot make them fail: they
    test what the corpus's citations rest on.
    test_glossary_oea_row_names_every_compendium_oea_title also reads the
    glossary's OEA row, and
    test_reference_manifest_set_aside_titles_are_catalogue_titles reads
    the reference catalogue and the reference acquisition manifest."""

    _HELD_SOURCE_CHECKS = (
        "test_compendium_neec_search_results_hold",
        "test_safe_basc_search_result_holds",
        "test_glossary_oea_row_names_every_compendium_oea_title",
        "test_cited_held_lines_carry_their_text",
        "test_reference_manifest_set_aside_titles_are_catalogue_titles")
    # Round 8 (review round 3, claude NOTE 4): the tests that read neither
    # a corpus file nor a held extract.
    _SELF_CHECKS = (
        "test_hmrc_submission_guard_catches_each_form",
        "test_border_force_guard_reads_the_governing_clause",
        "test_spanish_oea_guard_reads_each_occurrence",
        "test_section_11_12_guards_read_the_citing_clause",
        "test_class_docstring_states_the_test_count_and_held_checks")
    # What a corpus regression test calls to read the corpus.
    _CORPUS_READERS = re.compile(
        r"self\._(?:lines|corpus_lines|md_lines|section_lines|glossary_row"
        r"|glossary_sections|glossary_all_sections|matrix_cell"
        r"|taxonomy_paths)\(|\bREPO_ROOT\b|_load_build\(")

    GLOSSARY = "governance/register-glossary.md"
    SUPPLY_MATRIX = ("supply-chain/matrix-supply-chain-security-programme-"
                     "alignment.md")
    COMPLIANCE_MATRIX = "compliance/matrix-grc-compliance-alignment.md"
    LOGISTICS = "compliance/logistics/"
    IT_REGISTER = LOGISTICS + "register-ctpat-united-states-it-controls.md"
    MSC_REGISTER = LOGISTICS + "register-ctpat-united-states-msc-controls.md"
    PIP_REGISTER = LOGISTICS + "register-pip-canada-controls.md"
    BASC_ANNEX = LOGISTICS + "annex-basc-programme-overview.md"
    UK_ANNEX = LOGISTICS + "annex-aeo-united-kingdom-cybersecurity.md"
    UK_PROCEDURE = (LOGISTICS + "procedure-aeo-united-kingdom-self-"
                    "assessment.md")
    # Held extracts, relative to the grc_library_ref root.
    HELD_HMRC = ("programs/UK-AEO/UK-HMRC-Customs-Technical-Handbook-AEO-"
                 "AEOS-security-and-safety-criteria--full-text.md")
    COMPENDIUM = ("programs/WCO-AEO-Compendium/WCO-AEO-Compendium-2020--"
                  "full-text.md")
    HELD_SAFE = ("programs/WCO-SAFE/WCO-SAFE-Framework-of-Standards--"
                 "full-text.md")
    BASC_NORM = ("frameworks/BASC/BASC-International-Norm-V6-2022--CSMS--"
                 "full-text.md")
    BASC_603 = ("frameworks/BASC/BASC-International-Security-Standard-"
                "6.0.3-2022--basic-security-operational-controls--"
                "full-text.md")
    CTPAT_CHECKLIST = ("programs/CTPAT/CTPAT-Cybersecurity-Checklist-Sample--"
                       "full-text.md")
    MXCA_GUIDE = ("programs/AEO-MRA-Mexico-Canada/AEO-MRA-Mexico-Canada-"
                  "benefits-guide--full-text.md")
    BRAZIL_OEA = ("programs/Brazil-OEA/Brazil-OEA-implementation-guide--"
                  "full-text.md")
    ANPD_COOKIES = ("frameworks/Brazil-ANPD/Brazil-ANPD-Guia-Orientativo-"
                    "Cookies-e-Protecao-de-Dados-Pessoais-v1-2022--"
                    "full-text.md")
    HELD_LGPD = "legislation/Brazil/Brazil-LGPD-Lei-13709-2018--full-text.md"
    MARCO_CIVIL = ("legislation/Brazil/Brazil-Marco-Civil-da-Internet-Lei-"
                   "12965-2014--full-text.md")
    DC_200 = ("frameworks/AICPA/AICPA-DC-200-2018-SOC2-Description-"
              "Criteria-revised-2022-clean--full-text.md")
    AAG_SOP = ("frameworks/AICPA/AICPA-AAG-SOC-guide-reporting-on-controls-"
               "AAGSOP22E--full-text.md")

    @staticmethod
    def _lines(rel):
        return (REPO_ROOT / rel).read_text(encoding="utf-8").splitlines()

    @staticmethod
    def _taxonomy_paths():
        text = (REPO_ROOT / "taxonomy.yml").read_text(encoding="utf-8")
        return sorted(set(re.findall(r'^- path: "([^"]+)"', text, re.M)))

    def _corpus_lines(self):
        """Every (path, line) of the taxonomy documents and the README of
        each of their directories."""
        rels = set()
        for rel in self._taxonomy_paths():
            rels.add(rel)
            rels.add("/".join(rel.split("/")[:-1] + ["README.md"]))
        for rel in sorted(rels):
            if (REPO_ROOT / rel).is_file():
                for line in self._lines(rel):
                    yield rel, line

    def _glossary_sections(self):
        """The glossary's lettered sections: heading to the list of terms
        of its table rows, in file order."""
        sections, current = {}, None
        for line in self._lines(self.GLOSSARY):
            if line.startswith("## "):
                heading = re.fullmatch(r"## (\S+)", line)
                current = heading.group(1) if heading else None
                if current is not None:
                    sections[current] = []
                continue
            row = re.match(r"\| \*\*(.+?)\*\* \|", line)
            if row and current is not None:
                sections[current].append(row.group(1))
        return sections

    def _glossary_row(self, term):
        rows = [line for line in self._lines(self.GLOSSARY)
                if line.startswith(f"| **{term}** |")]
        self.assertEqual(len(rows), 1, rows)
        return rows[0]

    def _section_lines(self, rel, heading):
        """The lines under a level-2 heading, up to the next one."""
        lines = self._lines(rel)
        start = lines.index(heading) + 1
        end = start
        while end < len(lines) and not lines[end].startswith("## "):
            end += 1
        return lines[start:end]

    @staticmethod
    def _held_root():
        """The grc_library_ref checkout, looked for as
        tools/verify-reference-modules.py does: GRC_REF_PATH, then the
        sibling ../grc_library_ref. None when neither is present (CI holds
        no reference corpus)."""
        for candidate in (os.environ.get("GRC_REF_PATH"),
                          REPO_ROOT.parent / "grc_library_ref"):
            if candidate and Path(candidate).is_dir():
                return Path(candidate)
        return None

    def _held_lines(self, rel):
        """The held extract's lines, split on LF only; skips the test when
        the reference corpus is not present."""
        root = self._held_root()
        if root is None:
            self.skipTest("grc_library_ref not present (set GRC_REF_PATH "
                          "or check it out beside this repository)")
        return (root / rel).read_text(encoding="utf-8").split("\n")

    # -- research ERROR 1 to 3: BASC recognition within WCO SAFE.
    # The held 2025 Framework (programs/WCO-SAFE/) names no BASC: a
    # case-insensitive search of it for BASC and Business Alliance finds no
    # line (its header line 4 names CTPAT, PIP and EU AEO, not BASC). The
    # BASC International Norm V6-2022 (frameworks/BASC/, CSMS extract)
    # says, by clause, that it enables a company to "Implement and
    # complement programs such as CTPAT, Authorized Economic" / "Operator
    # (AEO), and others" (clause 1.1 e, lines 326 to 327) and, under "2"
    # "NORMATIVE REFERENCES" (lines 370 to 372), names "Framework of
    # Standards - World Customs Organization" (line 390); WBO is "a
    # member-led, not-forprofit international business organization"
    # (line 143). Its clause 0.1, "Prologue" (lines 134 to 136), says BASC
    # "also enjoys cooperation" / "agreements with 22 business and customs
    # organizations, including the World Customs" / "Organization (WCO)"
    # (lines 148 to 150); its "Foreword" is a separate clause, 0.2 (table of
    # contents line 26, heading line 250).
    _BASC_README = (
        "Multi-country private supply-chain security certification, "
        "predominantly Latin American, run by the World BASC Organization "
        "(WBO). The programme overview annex sets out what BASC's own norm "
        "says about its relationship to the WCO SAFE Framework and to "
        "customs AEO programmes.")
    _BASC_GLOSSARY = (
        "| **BASC** | Business Alliance for Secure Commerce. International "
        "private supply-chain security certification, predominantly Latin "
        "American, run by the World BASC Organization (WBO), a member-led "
        "business organization. See "
        "[`compliance/logistics/annex-basc-programme-overview.md`]"
        "(../compliance/logistics/annex-basc-programme-overview.md). |")
    _BASC_ANNEX_CLAIM = (
        "BASC is a private supply-chain security certification run by the "
        "World BASC Organization (WBO), a member-led business organization, "
        "and is widely adopted in Latin American trade and logistics "
        "operations. By BASC's own account, its International Norm V6-2022 "
        "is meant to help a company implement and complement programmes "
        "such as CTPAT and the Authorized Economic Operator (AEO) (clause "
        "1.1 e), and it lists the World Customs Organization (WCO) "
        "Framework of Standards among its normative references (clause 2). "
        "In clause 0.1 (Prologue) of the same Norm, BASC states that it has "
        "cooperation agreements with 22 business and customs organizations, "
        "the WCO among them. That cooperation agreement is BASC's own "
        "account and does not by itself establish recognition: BASC is not "
        "recorded in the WCO SAFE Framework (2025 edition), and recognition "
        "of BASC by the WCO is not confirmed by a held source.")
    _BASC_MATRIX_CELL = (
        "| Not confirmed by a held source: a private certification run by "
        "the WBO; the BASC International Norm V6-2022 lists the WCO "
        "Framework of Standards among its normative references (clause 2) "
        "|")

    def test_basc_recognition_within_wco_safe_removed(self):
        """Research ERROR 1 to 3 and WARN #10: the logistics README, the
        glossary and the BASC programme overview annex said BASC is
        recognized within the WCO SAFE Framework, and the supply chain
        programme matrix gave BASC "WCO SAFE Framework aligned" as its
        mutual recognition. The held 2025 Framework never names BASC. The
        README and the glossary drop the claim; the annex attributes what
        BASC says of itself to its own Norm, by clause, and says the WCO's
        recognition is not confirmed by a held source; the matrix cell
        says the same and names the Norm's normative reference. Round 6
        (claude NOTE 2): the annex cites clause 0.1 (Prologue), which holds
        the cooperation statement, not the Norm's separate Foreword (clause
        0.2), and says the agreement does not by itself establish
        recognition rather than stating that it is not recognition."""
        recognized = re.compile(r"(?i)recogni[sz]ed within")
        found = [f"{rel}: {line[:60]}" for rel, line in self._corpus_lines()
                 if "BASC" in line and recognized.search(line)]
        self.assertEqual(found, [])
        self.assertIn(self._BASC_README,
                      self._lines(self.LOGISTICS + "README.md"))
        self.assertEqual(self._glossary_row("BASC"), self._BASC_GLOSSARY)
        annex = [line for line in self._lines(self.BASC_ANNEX)
                 if "BASC is a private" in line]
        self.assertEqual(len(annex), 1, annex)
        self.assertIn(self._BASC_ANNEX_CLAIM, annex[0])
        self.assertNotIn("analogous to", annex[0])
        self.assertNotIn("foreword", annex[0])
        self.assertNotIn("is not recognition", annex[0])
        rows = [line for line in self._lines(self.SUPPLY_MATRIX)
                if line.startswith("| **BASC**:")]
        self.assertEqual(len(rows), 1, rows)
        self.assertTrue(rows[0].endswith(self._BASC_MATRIX_CELL), rows[0])
        self.assertNotIn("WCO SAFE Framework aligned", rows[0])

    # -- research WARN (the other eight carriers): derivation, overlap,
    # alignment and implementation claims.
    def test_held_back_programme_claims_are_reworded(self):
        """Research WARN #2 and #4 to #8, #11: the held-back lines said the
        UK AEO-S programme is the UK's implementation of the Framework, or
        derives from it, that the Framework is its international basis,
        that PIP aligns with it, that PIP and AEO-S both derive from it
        with significant overlap, and that NEEC aligns with it. None of
        the eleven held-back lines remains
        (DraftSiteRenderTests._WCO_REWORDED_BASIS_CLAIMS); the reworded
        lines the claim matcher still reads are pinned
        (_WCO_ATTRIBUTED_BASIS_CLAIMS) and each names the held source it
        rests on; the UK self-assessment purpose drops the clause, and
        the PIP mutual recognition note no longer calls AEO-S functionally
        comparable."""
        reworded = DraftSiteRenderTests._WCO_REWORDED_BASIS_CLAIMS
        attributed = DraftSiteRenderTests._WCO_ATTRIBUTED_BASIS_CLAIMS
        # Round 5 (codex WARN 3): no pinned count; the list must be
        # non-empty, and each line in it must be gone.
        self.assertTrue(reworded)
        for rel, old in reworded:
            with self.subTest(rel=rel, old=old[:50]):
                self.assertNotIn(old, self._lines(rel))
        for rel, new in attributed:
            with self.subTest(rel=rel, new=new[:50]):
                self.assertEqual(self._lines(rel).count(new), 1)
                self.assertRegex(new, r"WCO AEO Compendium \(2020\)|"
                                      r"Mexico-Canada AEO mutual recognition")
                self.assertNotRegex(
                    new, r"(?i)\bderives?\b|aligns with|implementation of "
                         r"the World Customs|international basis")
        # Round 3b narrowed the rest of this purpose line to the held HMRC
        # criteria (_UK_PROCEDURE_PURPOSE); the pin follows it.
        purpose = [line for line in self._lines(self.UK_PROCEDURE)
                   if line.startswith("HMRC tests AEO-S applicants")]
        self.assertEqual(purpose, [self._UK_PROCEDURE_PURPOSE])
        pip = "\n".join(self._lines(self.PIP_REGISTER))
        self.assertNotIn("functionally comparable", pip)
        self.assertIn(
            "That UK AEO-S certification is comparable to PIP is not "
            "confirmed by a held source; the WCO AEO Compendium (2020) lists "
            "both programmes (the UK's then reported as the European Union "
            "programme) among operational AEO programmes, and a Canada-UK "
            "mutual recognition arrangement is not recorded in it.", pip)

